package elastic

import (
	"fmt"
	"strings"
	"testing"

	"github.com/KarakoramDev/Karakoram/internal/engine/enginetest"
)

// Fixtures were generated by the real engine at 1cb6bd98 with the v0.4.5
// artifact payloads and the three prior supported Elastic release lines.
// Elastic itself uses explicit versioned upstream URLs rather than lock entries.
// No member is first converged or prepared by the current control plane.
func TestCPUpgradePreservesPreparedMembers(t *testing.T) {
	for _, version := range []string{"9.5.5", "9.4.8", "8.19.23"} {
		t.Run(version, func(t *testing.T) {
			p, rc, backend, native := coreSetup(t, 1)
			fixture := enginetest.RestorePreparedCPUpgrade(t, rc, fmt.Sprintf("testdata/cp-upgrade-%s.json", version))
			if !strings.Contains(strings.Join(fixture.Runtime.Prepare, "\n"), "elasticsearch-"+version) {
				t.Fatal("fixture lacks genuine preparation for the old Elastic release")
			}
			backend.services = enginetest.PreparedServices(fixture)
			var names []string
			for name := range fixture.Configs {
				names = append(names, name)
				if strings.HasPrefix(name, "demon") {
					backend.nodes[name] = version
				}
			}
			backend.calls = nil
			rc.Dialer = coreDialer{enginetest.LegacyNativeServer(t, fixture.Secrets[secretCA], fixture.Secrets[secretCAKey], names, native)}
			for range 3 {
				p = New(p.options)
				if _, err := p.Sync(t.Context(), rc); err != nil {
					t.Fatal(err)
				}
			}
			state, err := load(rc.Cluster)
			if err != nil {
				t.Fatal(err)
			}
			if state.Rolling != nil || state.Pending != nil || state.Phase != "ready" {
				t.Fatal("CP-only upgrade scheduled a config/version rollout")
			}
			for name, before := range fixture.Configs {
				after, err := p.MemberConfig(t.Context(), rc, name)
				if err != nil {
					t.Fatal(err)
				}
				enginetest.RequirePreparedConfig(t, name, before.EngineSpec, after.EngineSpec)
			}
			for _, call := range backend.calls {
				if strings.HasPrefix(call, "deploy:") {
					t.Fatalf("CP-only upgrade redeployed existing member: %s", call)
				}
			}
		})
	}
}
